	public sealed class LOGIN : INetworkProtocol
	{
		public Byte ServiceId { get; } = 7;
		public String ProtocolType { get; } = "LOGIN";
		public Int32 ProtocolVersion { get; } = 1;
		public String ProtocolDescription { get; } = "Login Server Messages";

		public INetworkMessage Dispatch(byte id)
        {
            switch (id)
            {
                case (1): return new MSG_CHARACTERINFO();
                case (2): return new MSG_CHARACTERLIST();
                case (3): return new MSG_CHARACTERSELECTED();
                case (4): return new MSG_CREATECHARACTER();
                case (5): return new MSG_CREATECHARACTERRESPONSE();
                case (6): return new MSG_DELETECHARACTER();
                case (7): return new MSG_DELETECHARACTERRESPONSE();
                case (8): return new MSG_REQUESTCHARACTERLIST();
                case (9): return new MSG_REQUESTSERVERLIST();
                case (10): return new MSG_SELECTCHARACTER();
                case (11): return new MSG_SERVERLIST();
                case (12): return new MSG_STARTCHARACTERLIST();
                case (13): return new MSG_USER_AUTHEN();
                case (14): return new MSG_USER_AUTHEN_RSP();
                case (15): return new MSG_USER_VALIDATE();
                case (16): return new MSG_USER_VALIDATE_RSP();
                case (17): return new MSG_DISCONNECT_LOGIN_AFK();
                case (18): return new MSG_LOGIN_NOT_AFK();
                case (19): return new MSG_LOGINSERVERSHUTDOWN();
                case (20): return new MSG_USER_ADMIT_IND();
                case (21): return new MSG_WEBCHARACTERINFO();
                case (22): return new MSG_USER_AUTHEN_V2();
                case (23): return new MSG_SAVECHARACTER();
                case (24): return new MSG_WEB_AUTHEN();
                case (25): return new MSG_WEB_VALIDATE();
                case (26): return new MSG_CHANGECHARACTERNAME();
                case (27): return new MSG_USER_AUTHEN_V3();
                case (28): return new MSG_LOGINLOGCHARACTERCREATION();
                default: throw new InternalException($"No message was found at ID {id} for this protocol!");
            }
        }

