	public sealed class PATCH : INetworkProtocol
	{
		public Byte ServiceId { get; } = 8;
		public String ProtocolType { get; } = "PATCH";
		public Int32 ProtocolVersion { get; } = 1;
		public String ProtocolDescription { get; } = "Patch Server Messages";

		public INetworkMessage Dispatch(byte id)
        {
            switch (id)
            {
                case (1): return new MSG_LATEST_FILE_LIST();
                case (2): return new MSG_LATEST_FILE_LIST_V2();
                case (3): return new MSG_NEXT_VERSION();
                default: throw new InternalException($"No message was found at ID {id} for this protocol!");
            }
        }

		public sealed class MSG_LATEST_FILE_LIST : INetworkMessage
		{
			public byte MessageOrder { get; } = 1;
			// Patch Client sends this message to request the latest file list.  Patch Server sends this message to tell the client where to get it.  
			public byte AccessLevel { get; } = 0;
			public byte ServiceId { get; } = 8;
			[DmlElement(DmlType.UINT)] public UInt32 LatestVersion;
			[DmlElement(DmlType.STR)] public ByteString ListFileName;
			[DmlElement(DmlType.UINT)] public UInt32 ListFileType;
			[DmlElement(DmlType.UINT)] public UInt32 ListFileTime;
			[DmlElement(DmlType.UINT)] public UInt32 ListFileSize;
			[DmlElement(DmlType.UINT)] public UInt32 ListFileCRC;
			[DmlElement(DmlType.STR)] public ByteString ListFileURL;
			[DmlElement(DmlType.STR)] public ByteString URLPrefix;
			[DmlElement(DmlType.STR)] public ByteString URLSuffix;
		}
		public sealed class MSG_LATEST_FILE_LIST_V2 : INetworkMessage
		{
			public byte MessageOrder { get; } = 2;
			// Patch Client sends this message to request the latest file list.  Patch Server sends this message to tell the client where to get it.  
			public byte AccessLevel { get; } = 0;
