			[DmlElement(DmlType.UINT)] public UInt32 ListFileType;
			[DmlElement(DmlType.UINT)] public UInt32 ListFileTime;
			[DmlElement(DmlType.UINT)] public UInt32 ListFileSize;
			[DmlElement(DmlType.UINT)] public UInt32 ListFileCRC;
			[DmlElement(DmlType.STR)] public ByteString ListFileURL;
			[DmlElement(DmlType.STR)] public ByteString URLPrefix;
			[DmlElement(DmlType.STR)] public ByteString URLSuffix;
			[DmlElement(DmlType.STR)] public ByteString Locale;
		}
		public sealed class MSG_NEXT_VERSION : INetworkMessage
		{
			public byte MessageOrder { get; } = 3;
			// Patch Client sends this message with the current version of a specific package.  Patch Server replies with the next version of the specific package.
			public byte AccessLevel { get; } = 0;
			public byte ServiceId { get; } = 8;
			[DmlElement(DmlType.STR)] public ByteString PkgName;
			[DmlElement(DmlType.INT)] public Int32 Version;
			[DmlElement(DmlType.STR)] public ByteString URLPrefix;
			[DmlElement(DmlType.STR)] public ByteString FileName;
			[DmlElement(DmlType.INT)] public Int32 FileType;
		}
	}
